async function o(){try{const e=await(await fetch("/api/session-user",{method:"GET",credentials:"include"})).json();if(!e.success||!e.user||e.user.Role==="Trainer"){localStorage.removeItem("staffUser"),window.location.href="../Forbidden.html";return}localStorage.setItem("staffUser",JSON.stringify(e.user))}catch(t){console.error("Session validation failed:",t),localStorage.removeItem("staffUser"),window.location.href="../Forbidden.html"}}function a(){const t=window.location.pathname.split("/").pop();document.querySelectorAll(".navbar a").forEach(e=>{e.getAttribute("href")===t?e.classList.add("active"):e.classList.remove("active")})}document.addEventListener("DOMContentLoaded",()=>{o(),a(),document.getElementById("logoutLink").addEventListener("click",function(t){t.preventDefault(),fetch("/api/logout",{method:"POST",credentials:"include"}).then(()=>{localStorage.removeItem("staffUser"),window.location.href="../homepage.html"}).catch(e=>console.error("Logout failed:",e))})});
